return { html: "<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Revenue Intelligence Report</title>
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:32px 16px;background:#f6f6f6;color:#161616}
main{max-width:760px;margin:auto;background:#fff;border:1px solid #ddd;border-radius:12px;padding:28px}
textarea{width:100%;min-height:128px;box-sizing:border-box;padding:12px;font:inherit}
button{margin-top:12px;padding:10px 16px;background:#111;color:#fff;border:0;border-radius:8px}
#result{margin-top:24px;padding-top:20px;border-top:1px solid #ddd}.hidden{display:none}.error{color:#9d1c1c}
pre{white-space:pre-wrap;word-break:break-word;background:#f4f4f4;padding:12px;border-radius:8px}
</style></head><body><main>
<h1>Revenue Intelligence Report</h1>
<p>Ask a governed Revenue/RevOps question. Your identity and data scope come from company SSO.</p>
<form id="f"><label for="q">Report question</label>
<textarea id="q" maxlength="1000" required placeholder="What is open pipeline this quarter by sales rep?"></textarea>
<button id="b" type="submit">Run report</button></form>
<div id="status" role="status" aria-live="polite"></div><section id="result" class="hidden"></section>
<script>
(()=>{'use strict';const f=document.getElementById('f'),q=document.getElementById('q'),b=document.getElementById('b'),s=document.getElementById('status'),r=document.getElementById('result');
const clear=e=>{while(e.firstChild)e.removeChild(e.firstChild)};
const add=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text==null?'':String(text);if(cls)e.className=cls;r.appendChild(e);return e};
f.addEventListener('submit',async e=>{e.preventDefault();clear(r);r.classList.add('hidden');s.textContent='Running governed report…';b.disabled=true;
try{const resp=await fetch('/sso/report',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({question:q.value.trim(),delivery_channel:'api'})});
const body=await resp.json().catch(()=>({}));clear(r);r.classList.remove('hidden');
if(!resp.ok||body.status!=='success'){add('h2','Report unavailable','error');add('p',body?.error?.message||'The report request could not be completed safely.','error');if(body.request_id)add('p','Reference: '+body.request_id);s.textContent='';return}
const p=body.presentation||{},rep=body.report||{},sum=body.management_summary||{};
add('h2',p.title||sum.headline||rep.kpi_key||'Revenue report');if(p.summary||sum.summary)add('p',p.summary||sum.summary);
const facts=p.key_facts||sum.key_facts||[];if(facts.length){add('h3','Key facts');facts.slice(0,10).forEach(x=>add('div',x))}
if(sum.management_interpretation){add('h3','Management interpretation');add('p',sum.management_interpretation)}
if(sum.recommended_action){add('h3','Recommended action');add('p',sum.recommended_action)}
add('h3','Governed data');add('pre',JSON.stringify(p.data||{current_period:rep.current_period||null,previous_period:rep.previous_period||null,diagnostics:rep.diagnostics||null},null,2));
if(body.request_id)add('p','Reference: '+body.request_id);s.textContent='Report completed.'
}catch(_){clear(r);r.classList.remove('hidden');add('h2','Report unavailable','error');add('p','The reporting service could not be reached. Please try again later.','error');s.textContent=''}finally{b.disabled=false}})})();
</script></main></body></html>" };
